import type { ClaudeDraftImage } from '@renderer/session-runtime/state'

// Helpers for turning pasted / dropped / clipboard images into the
// `ClaudeDraftImage` payload shape the workspace runtime stores.
//
// Three ingress paths:
//   1. Files in `clipboardData.items` (the common case for a
//      copy-image-from-app → paste flow).
//   2. An `<img src="data:image/...">` embedded in an HTML fragment
//      (some browsers copy web images as HTML + data URL rather than
//      a real File).
//   3. `navigator.clipboard.read()` for cases (1) and (2) when
//      `clipboardData` came up empty (Electron picks a clipboard
//      representation per OS and some combinations only surface
//      through the async API).
//
// All three return the same `ClaudeDraftImage[]` so the caller can
// concat + dedupe uniformly.

// WHY only SUPPORTED_CLAUDE_IMAGE_FORMATS_TEXT, the two predicates,
// and the public ingress helpers below are exported: every other
// constant and helper in this file (MAX_CLAUDE_IMAGE_BYTES, the
// media-type Set, fileToDataUrl, parseDataUrl, estimateBase64...) is
// an internal implementation detail used only inside this module's
// predicates and ingress functions. The user-facing format-text
// string is exported because the composer toast needs it; the two
// predicates are exported because the paste hook gates on them.
const MAX_CLAUDE_IMAGE_BYTES = 5 * 1024 * 1024

const SUPPORTED_CLAUDE_IMAGE_MEDIA_TYPES = new Set([
  'image/png',
  'image/jpeg',
  'image/gif',
  'image/webp',
])

export const SUPPORTED_CLAUDE_IMAGE_FORMATS_TEXT = 'PNG, JPEG, GIF, WebP'

export function isSupportedClaudeImageMediaType(mediaType: string): boolean {
  return SUPPORTED_CLAUDE_IMAGE_MEDIA_TYPES.has(mediaType.toLowerCase())
}

export function exceedsClaudeImageSizeLimit(image: ClaudeDraftImage): boolean {
  return estimateBase64DecodedBytes(image.base64Data) > MAX_CLAUDE_IMAGE_BYTES
}

function fileToDataUrl(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader()
    reader.onerror = () => reject(reader.error ?? new Error('failed to read file'))
    reader.onload = () => {
      if (typeof reader.result === 'string') resolve(reader.result)
      else reject(new Error('file reader returned non-string result'))
    }
    reader.readAsDataURL(file)
  })
}

function parseDataUrl(dataUrl: string): { mediaType: string; base64Data: string } {
  const match = /^data:([^;]+);base64,(.+)$/.exec(dataUrl)
  if (!match) {
    throw new Error('unsupported image data url')
  }
  return {
    mediaType: match[1] ?? 'image/png',
    base64Data: match[2] ?? '',
  }
}

// Rough byte-count estimate: 4 base64 chars encode 3 bytes, minus
// 1 byte per `=` pad char. We only use this for the size-limit gate,
// so approximate is fine — a 5 MB cap enforced at ±16 bytes is still
// effectively a 5 MB cap.
function estimateBase64DecodedBytes(base64Data: string): number {
  const normalized = base64Data.trim()
  if (normalized.length === 0) return 0
  const padding = normalized.endsWith('==') ? 2 : normalized.endsWith('=') ? 1 : 0
  return Math.floor((normalized.length * 3) / 4) - padding
}

export function parseImagesFromHtml(html: string): ClaudeDraftImage[] {
  if (!html.trim()) return []
  // Some browsers copy web images as an HTML fragment containing an
  // embedded data URL rather than exposing a File in clipboardData.
  // We only parse this into a detached Document and read `img.src` —
  // the HTML is never injected into the live DOM.
  const doc = new DOMParser().parseFromString(html, 'text/html')
  const images: ClaudeDraftImage[] = []
  for (const img of Array.from(doc.images)) {
    const src = img.getAttribute('src')?.trim() ?? ''
    if (!src.startsWith('data:image/')) continue
    try {
      const { mediaType, base64Data } = parseDataUrl(src)
      images.push({
        id: crypto.randomUUID(),
        mediaType,
        base64Data,
        previewUrl: src,
        filename: img.getAttribute('alt')?.trim() || 'Pasted image',
      })
    } catch {
      // Ignore malformed HTML image sources and keep scanning.
    }
  }
  return images
}

// Synchronous "does this clipboard plausibly carry an image?" check.
//
// WHY this exists separately from `handlePaste`: `usePasteToFocus`
// needs to decide — synchronously, during paste-event dispatch —
// whether to take the async image path or just append text now. The
// two SYNCHRONOUSLY-knowable image signals are (1) a `clipboardData`
// item with an `image/*` type and (2) a data-URL `<img>` inside the
// `text/html` representation. This deliberately does NOT cover the
// `navigator.clipboard.read()` fallback `handlePaste` uses — that
// fallback is inherently async and cannot inform a synchronous
// decision. A paste whose image surfaces ONLY through that async
// API will be treated as non-image by paste-to-focus; that is an
// accepted, rare gap (the alternative — awaiting a clipboard probe
// on every plain-text paste — delays and can reorder ordinary text
// pastes, which is the common case and matters more).
export function clipboardHasImageCandidate(
  clipboardData: DataTransfer | null,
): boolean {
  if (!clipboardData) return false
  for (const item of Array.from(clipboardData.items)) {
    if (item.type.startsWith('image/')) return true
  }
  return parseImagesFromHtml(clipboardData.getData('text/html')).length > 0
}

export async function filesToDraftImages(files: File[]): Promise<ClaudeDraftImage[]> {
  return Promise.all(
    files.map(async file => {
      const previewUrl = await fileToDataUrl(file)
      const { mediaType, base64Data } = parseDataUrl(previewUrl)
      return {
        id: crypto.randomUUID(),
        mediaType,
        base64Data,
        previewUrl,
        filename: file.name || 'Pasted image',
      } satisfies ClaudeDraftImage
    }),
  )
}

export async function readImagesFromClipboard(): Promise<ClaudeDraftImage[]> {
  if (!navigator.clipboard?.read) return []
  const items = await navigator.clipboard.read()
  const images: ClaudeDraftImage[] = []
  for (const item of items) {
    const imageType = item.types.find(type => type.startsWith('image/'))
    if (!imageType) continue
    const blob = await item.getType(imageType)
    const previewUrl = await fileToDataUrl(new File([blob], 'Pasted image', { type: imageType }))
    const { mediaType, base64Data } = parseDataUrl(previewUrl)
    images.push({
      id: crypto.randomUUID(),
      mediaType,
      base64Data,
      previewUrl,
      filename: 'Pasted image',
    })
  }
  return images
}

