import { getRendererProviderCapabilities } from '@providers/registry.renderer.capabilities'
import type { AgentProviderKind } from '@shared/types/providerKind'
import { useCallback } from 'react'

import type { SessionId } from '@renderer/workspace/types'
import type { ClaudeDraftImage } from '@renderer/session-runtime/state'
import {
  SUPPORTED_CLAUDE_IMAGE_FORMATS_TEXT,
  exceedsClaudeImageSizeLimit,
  filesToDraftImages,
  isSupportedClaudeImageMediaType,
  parseImagesFromHtml,
  readImagesFromClipboard,
} from '@renderer/workspace/tile-tree/TileLeaf/claudeImages'

// Image-paste handler for the composer. Claude-only: Codex doesn't
// accept inline image content, so we fall through to the browser's
// default paste handling for that provider.
//
// Three clipboard ingress paths live here (pluralised from what a
// naive `clipboardData.items` check would give us):
//
//   1. `e.clipboardData.items` File objects (the typical copy-image-
//      from-app flow on macOS / Windows).
//   2. `<img src="data:image/...">` embedded in `text/html` (some
//      browsers copy web images as HTML fragments rather than real
//      Files).
//   3. `navigator.clipboard.read()` fallback (covers the case where
//      Electron picks a clipboard representation that doesn't
//      surface through synchronous `clipboardData`).
//
// We also gate on media type (Claude supports PNG/JPEG/GIF/WebP)
// and a 5 MB size cap — both enforced with a toast on violation
// and a short-circuit return. Validated images are appended into
// the draft-images store via setDraftImages; the hook does the
// append internally so callers only need to consume handlePaste
// and removeDraftImage (paste-only ingress).
//
// `e.preventDefault()` is called whenever we handle the paste so
// the default "paste as text" behavior doesn't leak data URL blobs
// into the textarea.
//
// WHY the event param is a structural `ClipboardLike` and not
// `React.ClipboardEvent`:
//   `handlePaste` has two callers now. The composer textarea passes
//   a React synthetic `ClipboardEvent`; `usePasteToFocus` passes a
//   *native* DOM `ClipboardEvent` (from a document-level listener,
//   so the paste can be routed into the composer even when DOM
//   focus drifted off the textarea — see issue #135). Both expose
//   `clipboardData` and `preventDefault`, so the handler depends on
//   that shape only. Native `ClipboardEvent.clipboardData` is
//   nullable (`DataTransfer | null`); React's is not — the wider
//   nullable type is the safe common denominator and the handler
//   guards for null.
type ClipboardLike = {
  clipboardData: DataTransfer | null
  preventDefault: () => void
}

// Result of a paste attempt. `handledImages` lets a caller decide
// whether to ALSO route the clipboard's text payload somewhere:
// `usePasteToFocus` skips its text-append step when images were
// detected, mirroring the textarea's existing "images win over
// text on a mixed paste" behaviour.
export type ImagePasteResult = { handledImages: boolean }

export function useClaudeImagePaste({
  provider,
  sessionId,
  setDraftImages,
  showToast,
}: {
  provider: AgentProviderKind
  sessionId: SessionId
  setDraftImages: (
    sessionId: SessionId,
    next: (prev: ClaudeDraftImage[]) => ClaudeDraftImage[],
  ) => void
  showToast: (message: string) => void
}) {
  const appendDraftImages = useCallback(
    (images: ClaudeDraftImage[]) => {
      if (images.length === 0) return
      setDraftImages(sessionId, prev => [...prev, ...images])
    },
    [sessionId, setDraftImages],
  )

  const removeDraftImage = useCallback(
    (imageId: string) => {
      setDraftImages(sessionId, prev => prev.filter(image => image.id !== imageId))
    },
    [sessionId, setDraftImages],
  )

  const handlePaste = useCallback(
    async (e: ClipboardLike): Promise<ImagePasteResult> => {
      // Providers without inline-image content fall through, so the caller
      // routes the clipboard's text instead.
      const capabilities = getRendererProviderCapabilities(provider)
      if (!capabilities.supportsImageAttachments) {
        // WHY say so (#1250 row 7): an image pasted into a Codex, OpenCode,
        // Grok or Pi composer was dropped with nothing said. The wording is
        // about THIS composer, not the provider (#1426 review b): Grok's own
        // TUI attaches clipboard images in Terminal view, where a paste goes
        // to the TUI and this hook never runs.
        //
        // What counts as an image (#1426 review a, b):
        //   - an image FILE item, with or without text. A mixed paste pastes
        //     its text and says the image was left out ("see attached" with
        //     no attachment is the silent loss);
        //   - a data-URL <img> in text/html with NO text. A web-page copy
        //     carries <img> beside its text, and that text paste stays silent;
        //   - with nothing else at all, an image only the async clipboard API
        //     shows (an Electron/macOS shape claudeImages.ts documents).
        // Everything is read synchronously first; the event's data is only
        // reliable during dispatch.
        const data = e.clipboardData
        if (!data) return { handledImages: false }
        const text = data.getData('text/plain')
        const hasImageFile = Array.from(data.items).some(item => item.kind === 'file' && item.type.startsWith('image/'))
        const html = data.getData('text/html')
        const hasHtmlImage = parseImagesFromHtml(html).length > 0
        const where = `${capabilities.shortLabel} from this composer`
        if (hasImageFile && text) {
          showToast(`Pasted images can't be sent to ${where}; only the text was pasted.`)
        } else if (hasImageFile || (hasHtmlImage && !text)) {
          showToast(`Pasted images can't be sent to ${where}.`)
        } else if (!text && !html && data.items.length === 0) {
          const asyncImages = await readImagesFromClipboard().catch(() => [])
          if (asyncImages.length > 0) showToast(`Pasted images can't be sent to ${where}.`)
        }
        return { handledImages: false }
      }
      const clipboardData = e.clipboardData
      if (!clipboardData) return { handledImages: false }

      // Read everything off `clipboardData` SYNCHRONOUSLY before the
      // first `await`. A ClipboardEvent's data is only reliably
      // readable during synchronous dispatch — once we await,
      // `items` / `getData` may come back empty. The `File` objects
      // from `getAsFile()` stay valid after the await; the live
      // `clipboardData` accessor does not. These reads sit OUTSIDE
      // the try so `hadImageEvidence` is visible to the catch below.
      const itemFiles = Array.from(clipboardData.items)
        .map(item => item.type.startsWith('image/') ? item.getAsFile() : null)
        .filter((file): file is File => Boolean(file && file.type.startsWith('image/')))
      const htmlImages = parseImagesFromHtml(clipboardData.getData('text/html'))

      // Whether the clipboard SYNCHRONOUSLY showed an image. This
      // decides the catch-block's return value below: a throw on a
      // paste that never had an image must NOT report
      // `handledImages: true`, or `usePasteToFocus` would drop the
      // user's plain text. (`readImagesFromClipboard()` — the async
      // fallback — only runs when there is no such evidence, so a
      // throw there means "probe failed", not "image handling
      // failed".)
      const hadImageEvidence = itemFiles.length > 0 || htmlImages.length > 0

      try {
        let images: ClaudeDraftImage[] = htmlImages
        if (itemFiles.length > 0) {
          e.preventDefault()
          const fileImages = await filesToDraftImages(itemFiles)
          const existing = new Set(images.map(image => image.previewUrl))
          images = [
            ...images,
            ...fileImages.filter(image => !existing.has(image.previewUrl)),
          ]
        } else if (images.length === 0) {
          // Async fallback for clipboards that don't surface an
          // image synchronously. NOTE: the `preventDefault()` here
          // lands AFTER the await, by which point the browser's
          // native paste has already run — so this branch cannot
          // reliably suppress native paste. In practice an image
          // paste carries no useful `text/plain`, so nothing
          // visible leaks; only synchronous item/html image paths
          // (above / below) suppress native paste reliably. This is
          // a pre-existing limitation, called out here rather than
          // fixed so the behaviour isn't silently relied upon.
          // `usePasteToFocus` never reaches this branch — it only
          // calls handlePaste when a synchronous image candidate
          // exists.
          images = await readImagesFromClipboard()
          if (images.length > 0) {
            e.preventDefault()
          }
        } else {
          e.preventDefault()
        }
        if (images.length === 0) return { handledImages: false }
        // From here on at least one image was detected — even the
        // rejection paths below count as "handled images" so the
        // caller does NOT additionally paste text: the user's
        // intent was an image, and a toast already explained why it
        // didn't land.
        const unsupported = images.find(
          image => !isSupportedClaudeImageMediaType(image.mediaType),
        )
        if (unsupported) {
          showToast(
            `Unsupported image format: ${unsupported.mediaType}. Claude supports ${SUPPORTED_CLAUDE_IMAGE_FORMATS_TEXT}.`,
          )
          return { handledImages: true }
        }
        const oversized = images.find(exceedsClaudeImageSizeLimit)
        if (oversized) {
          showToast(
            `Image is too large. Claude supports pasted images up to 5 MB.`,
          )
          return { handledImages: true }
        }
        appendDraftImages(images)
        return { handledImages: true }
      } catch (err) {
        console.warn('[TileLeaf] image paste failed', err)
        // Report `handledImages` by EVIDENCE, not unconditionally.
        // If there was a real image (sync evidence) and decoding it
        // threw, count it handled — a toast explained the failure
        // and we must not also dump a data-URL blob as text. But if
        // there was NO image evidence (the throw came from the
        // async `readImagesFromClipboard()` probe on a plain-text
        // paste), report `false` so the caller still appends the
        // user's text instead of silently swallowing it.
        if (hadImageEvidence) showToast('Image paste failed.')
        return { handledImages: hadImageEvidence }
      }
    },
    [appendDraftImages, provider, showToast],
  )

  return { handlePaste, removeDraftImage }
}

import { fireEvent, render } from '@testing-library/react'
import { useRef } from 'react'
import { afterEach, describe, expect, it, vi } from 'vitest'

import { usePasteToFocus } from './usePasteToFocus'

// #1426 verification a: a paste landing outside the composer (paste-to-focus)
// whose image only the async clipboard API shows arrives as an EMPTY event:
// no text, no HTML, no items. It never reached the shared image handler, so
// nothing was said (and Claude never attached it). It now does; ordinary text
// still appends synchronously and never calls the handler.

function Harness({ handlePaste }: { handlePaste: Parameters<typeof usePasteToFocus>[0]['handlePaste'] }) {
  const inputRef = useRef<HTMLTextAreaElement>(null)
  usePasteToFocus({ focused: true, sessionId: 's1' as never, inputRef, setDraftInput: vi.fn(), handlePaste })
  return <textarea aria-label="Composer" ref={inputRef} readOnly />
}

afterEach(() => { document.body.replaceChildren() })

describe('paste-to-focus and an async-only image', () => {
  it('hands an empty paste event to the image handler', () => {
    const handlePaste = vi.fn(async () => ({ handledImages: false }))
    render(<Harness handlePaste={handlePaste} />)
    fireEvent.paste(document.body, { clipboardData: new DataTransfer() })
    expect(handlePaste).toHaveBeenCalledTimes(1)
  })

  it('never hands ordinary text to it', () => {
    const handlePaste = vi.fn(async () => ({ handledImages: false }))
    render(<Harness handlePaste={handlePaste} />)
    const clipboard = new DataTransfer()
    clipboard.setData('text/plain', 'hello')
    fireEvent.paste(document.body, { clipboardData: clipboard })
    expect(handlePaste).not.toHaveBeenCalled()
  })
})

